using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;

namespace FSMigrator {
public sealed class AppLanguage {
 public string Code {get;private set;} public string Name {get;private set;} readonly Dictionary<string,string> strings;
 public AppLanguage(string code,string name,string[] keys,string[] values){if(values.Length!=keys.Length)throw new InvalidDataException("Invalid app translation: "+code+" ("+values.Length+"/"+keys.Length+")");Code=code;Name=name;strings=keys.Zip(values,(k,v)=>new{k,v}).ToDictionary(x=>x.k,x=>x.v);}
 public string this[string key]{get{return strings.ContainsKey(key)?strings[key]:key;}}
 public override string ToString(){return Name;}
}
public static class AppLocalization {
 static readonly string[] Keys={"Scanning","Ready","Action","ReadyDescription","NoCompatible","Profiles","Assignments","Axes","Ambiguous","CloseApps","NothingChanged","Transfer","Rescan","Restore","Details","GameProfiles","ChangeResult","Unchanged","BackupSection","BackupStored","ChangeBackup","SaveReport","Interrupted","DiagnosticSaved","StateChanged","TransferDone","TransferMessage","TransferTitle","NoBackup","WrongInstall","Restored","RestoreTitle","BackupDescription","OperationFailed","Language","SaveForImport","Advanced","AdvancedHint","WriteToGame","ConfirmWriteTitle","ConfirmWriteBody","PreviewTitle","ColSource","ColTarget","ColBindings","ColAxes","SkippedList","SkippedItem","ImportSteps","ExportTitle","ExportDone","CoachTitle","CoachSteps","SteamPrompt","SteamApply","Device","Category","NothingToExport","WriteRequiresConfirm","ExportFolderDescription"};
 static string[] V(string text){return text.Split(new[]{'|'});}
 static AppLanguage A(string code,string name,string text){return new AppLanguage(code,name,Keys,V(text));}
